      name={notebook.name}
      type="notebook"
      isActive={isActive}
      style={style}
      href={`/project/${projectRef}/explorer/notebook/${notebook.id}`}
      onDoubleClick={() => tabs.makeTabPermanent(createTabId('notebook', { id: notebook.id }))}
      onSelectDelete={() =>
        onSelectDelete({ id: notebook.id, type: 'notebook', name: notebook.name })
